// @ts-nocheck

import { NIL, RBTreeIdx, BeachPool } from "#core/scripts/external/TypeScript-Voronoi-master/src/rbtree-pool.js";
import { CircleEventHeap } from "#core/scripts/external/TypeScript-Voronoi-master/src/circle-event-heap.js";
import { Vertex } from "#core/scripts/external/TypeScript-Voronoi-master/src/vertex.js";
import { Edge } from "#core/scripts/external/TypeScript-Voronoi-master/src/edge.js";
import { Cell } from "#core/scripts/external/TypeScript-Voronoi-master/src/cell.js";
import { Site } from "#core/scripts/external/TypeScript-Voronoi-master/src/site.js";
import { Diagram } from "#core/scripts/external/TypeScript-Voronoi-master/src/diagram.js";
import { Halfedge } from "#core/scripts/external/TypeScript-Voronoi-master/src/halfedge.js";
import { BoundingBox } from "#core/scripts/external/TypeScript-Voronoi-master/src/bounding_box.js";

const EPSILON = 1e-9;

export class Voronoi {
	//
	// members
	//
	vertices: Vertex[];
	edges: Edge[];
	cells: Cell[];

	toRecycle: Diagram;

	// Beach-section RB-tree backed by a typed-array struct-of-arrays pool.
	beachPool: BeachPool;
	beachTree: RBTreeIdx;

	// Circle-event priority queue. Entries are referenced by an event id
	// (a monotonic counter, reset per compute()). Heap holds (yBottom, x, ev);
	// metadata is held in parallel typed arrays indexed by ev. Stale entries
	// (whose owning arc has been detached) are filtered lazily at the heap top.
	circleHeap: CircleEventHeap;
	eventArcIdx: Int32Array;
	eventX: Float64Array;
	eventYcenter: Float64Array;
	eventCount: number;
	eventCapacity: number;

	vertexJunkyard: Vertex[];
	edgeJunkyard: Edge[];
	cellJunkyard: Cell[];

	// When true, createEdge() does not construct or push Halfedge objects.
	// Used by the centroid-only fast path which skips closeCells/prepareHalfedges.
	private skipHalfedges: boolean;

	// Reusable scratch buffers for accumulateCentroids(). Grown lazily, zeroed
	// per call. Saves O(N) allocations + a Minor GC visible in profiles.
	private caArea: Float64Array;
	private caSumX: Float64Array;
	private caSumY: Float64Array;
	private caEvents: number[][];
	private caCapacity: number;
	// Largest n seen so far; tracked so we can clear stale per-cell event lists
	// past current n when a later call shrinks (Lloyd can drop sites past bbox).
	private caLastN: number;

	constructor() {
		this.vertices = null;
		this.edges = null;
		this.cells = null;
		this.toRecycle = null;
		this.beachPool = null;
		this.beachTree = null;
		this.circleHeap = null;
		this.eventArcIdx = null;
		this.eventX = null;
		this.eventYcenter = null;
		this.eventCount = 0;
		this.eventCapacity = 0;
		this.vertexJunkyard = [];
		this.edgeJunkyard = [];
		this.cellJunkyard = [];
		this.skipHalfedges = false;
		this.caArea = null;
		this.caSumX = null;
		this.caSumY = null;
		this.caEvents = null;
		this.caCapacity = 0;
		this.caLastN = 0;
	}

	//
	// public methods
	//

	// ---------------------------------------------------------------------------
	// Top-level Fortune loop
	// rhill 2011-05-19:
	//   Voronoi sites are kept client-side now, to allow
	//   user to freely modify content. At compute time,
	//   *references* to sites are copied locally.
	compute(sites: Site[], bbox: BoundingBox) {
		// to measure execution time
		let startTime = Date.now();

		this.runSweepAndClip(sites, bbox);

		//   add missing edges in order to close opened cells
		this.closeCells(bbox);

		// to measure execution time
		let stopTime = Date.now();

		// prepare return values
		let diagram = new Diagram();
		diagram.cells = this.cells;
		diagram.edges = this.edges;
		diagram.vertices = this.vertices;
		diagram.execTime = stopTime - startTime;

		// clean up
		this.reset();

		return diagram;
	}

	// Lloyd-relaxation fast path: runs the Fortune sweep + edge clipping but
	// skips halfedge construction, halfedge sorting, cell-closing, and the
	// Diagram object. Computes per-cell centroids directly from edge endpoints,
	// using direction-aware shoelace contributions per (lSite, rSite) edge plus
	// CCW bbox-border closure for cells whose edges touch the bbox.
	//
	// `outX`/`outY` are filled at indices matching the cell ids assigned during
	// the sweep (i.e., outX[site.id] is the centroid x of `site`'s cell). For
	// cells with degenerate (≈0) area the site's existing position is written.
	computeCentroids(sites: Site[], bbox: BoundingBox, outX: Float64Array, outY: Float64Array): void {
		this.skipHalfedges = true;
		this.runSweepAndClip(sites, bbox);
		this.accumulateCentroids(bbox, sites, outX, outY);
		this.skipHalfedges = false;

		// Self-recycle: stash the just-allocated cells/edges/vertices so the
		// next compute()/computeCentroids() can pull them from the junkyards
		// instead of allocating fresh objects.
		if (this.cells.length > 0) {
			const synth = new Diagram();
			synth.vertices = this.vertices;
			synth.edges = this.edges;
			synth.cells = this.cells;
			this.toRecycle = synth;
		}
		this.reset();
	}

	private runSweepAndClip(sites: Site[], bbox: BoundingBox): void {
		// init internal state
		this.reset();

		// Pre-grow pools so the hot loop avoids reallocation. Beachline carries
		// roughly 2N sections, the circle-event queue at most ~3N events total.
		this.beachPool.ensureCapacity(sites.length * 2);
		this.ensureEventCapacity(sites.length * 3);

		// any diagram data available for recycling?
		if (this.toRecycle) {
			this.vertexJunkyard.push(...this.toRecycle.vertices);
			this.edgeJunkyard.push(...this.toRecycle.edges);
			this.cellJunkyard.push(...this.toRecycle.cells);
			this.toRecycle = null;
		}

		// Initialize site event queue
		let siteEvents = sites.slice(0);
		siteEvents.sort((a, b) => b.y - a.y || b.x - a.x);

		const heap = this.circleHeap;
		const eventArcIdx = this.eventArcIdx;
		const beachCircleEventIdx = this.beachPool.circleEventIdx;

		// process queue
		let site = siteEvents.pop(),
			siteid = 0,
			xsitex, // to avoid duplicate sites
			xsitey,
			cells = this.cells,
			circleEv: number,
			circleY: number,
			circleX: number;

		// main loop
		for (;;) {
			// Lazy-skip stale heap entries: an entry is stale when its arc's
			// circleEventIdx no longer points back at it (set to NIL by
			// detachCircleEvent or replaced by a newer event). Read the heap's
			// fields directly to avoid method-dispatch overhead on non-JIT
			// platforms; pushes/pops below may reassign heap.indices on resize,
			// so we re-read each iteration.
			let heapIndices = heap.indices;
			while (heap.size > 0) {
				const ev = heapIndices[0];
				if (beachCircleEventIdx[eventArcIdx[ev]] === ev) break;
				heap.pop();
			}

			if (heap.size > 0) {
				heapIndices = heap.indices;
				circleEv = heapIndices[0];
				circleY = heap.y[0];
				circleX = heap.x[0];
			} else {
				circleEv = NIL;
			}

			// add beach section
			if (site && (circleEv === NIL || site.y < circleY || (site.y === circleY && site.x < circleX))) {
				// only if site is not a duplicate
				if (site.x !== xsitex || site.y !== xsitey) {
					// first create cell for new site
					cells[siteid] = this.createCell(site);
					site.id = siteid++;
					// then create a beachsection for that site
					this.addBeachsection(site);
					// remember last site coords to detect duplicate
					xsitey = site.y;
					xsitex = site.x;
				}

				site = siteEvents.pop();
			}

			// remove beach section
			else if (circleEv !== NIL) {
				heap.pop();
				this.removeBeachsection(eventArcIdx[circleEv]);
			}

			// all done, quit
			else {
				break;
			}
		}

		// wrapping-up:
		//   connect dangling edges to bounding box
		//   cut edges as per bounding box
		//   discard edges completely outside bounding box
		//   discard edges which are point-like
		this.clipEdges(bbox);
	}

	// Walk all (clipped) edges to accumulate per-cell shoelace integrals, then
	// add bbox-border closure contributions for cells whose edges terminate on
	// the bbox. Output is per-cell centroid in outX/outY (cell index = site.id).
	private accumulateCentroids(bbox: BoundingBox, sites: Site[], outX: Float64Array, outY: Float64Array): void {
		const xl = bbox.xl,
			xr = bbox.xr,
			yt = bbox.yt,
			yb = bbox.yb;
		const w = xr - xl;
		const h = yb - yt;
		const perim = 2 * (w + h);
		const eps = EPSILON;

		const n = this.cells.length;
		const edges = this.edges;

		// Reuse cached scratch buffers; grow on first use or when N grows past
		// previous capacity. Same growth policy as eventCapacity above.
		if (this.caCapacity < n) {
			let cap = this.caCapacity || 1024;
			while (cap < n) cap *= 2;
			this.caArea = new Float64Array(cap);
			this.caSumX = new Float64Array(cap);
			this.caSumY = new Float64Array(cap);
			this.caEvents = new Array(cap);
			this.caCapacity = cap;
		}
		const cellArea = this.caArea;
		const cellSumX = this.caSumX;
		const cellSumY = this.caSumY;
		const cellEvents = this.caEvents;
		cellArea.fill(0, 0, n);
		cellSumX.fill(0, 0, n);
		cellSumY.fill(0, 0, n);
		// Per-cell event lists: clear any leftovers from prior call. Inner
		// arrays themselves are kept so border cells reuse their backing storage.
		// Clear up to max(n, caLastN) so a smaller-n call doesn't leave stale
		// events at indices a later larger-n call would walk.
		const clearLen = n > this.caLastN ? n : this.caLastN;
		for (let i = 0; i < clearLen; i++) {
			const e = cellEvents[i];
			if (e !== undefined) e.length = 0;
		}
		this.caLastN = n;

		for (let i = 0, ne = edges.length; i < ne; i++) {
			const edge = edges[i];
			const lId = edge.lSite.id;
			const rId = edge.rSite.id;
			const va = edge.va;
			const vb = edge.vb;
			const ax = va.x,
				ay = va.y;
			const bx = vb.x,
				by = vb.y;

			// Direction-aware shoelace: lSite walks va->vb, rSite walks vb->va.
			const cross = ax * by - ay * bx;
			const sx = ax + bx;
			const sy = ay + by;
			cellArea[lId] += cross;
			cellSumX[lId] += sx * cross;
			cellSumY[lId] += sy * cross;
			cellArea[rId] -= cross;
			cellSumX[rId] -= sx * cross;
			cellSumY[rId] -= sy * cross;

			// Bbox-touch detection. A point is on the bbox iff one of x/y is
			// equal (within eps) to a bbox side. Inline so we can also collect
			// the CCW position scalar without re-checking sides.
			// CCW order with y-down screen coords:
			//   left side (top->bottom): pos = y - yt, range [0, h]
			//   bottom side (left->right): pos = h + (x - xl), range [h, h+w]
			//   right side (bottom->top): pos = h + w + (yb - y), range [h+w, 2h+w]
			//   top side (right->left): pos = 2h + w + (xr - x), range [2h+w, perim]
			let aPos = -1;
			if (ax - xl < eps && ax - xl > -eps) aPos = ay - yt;
			else if (ay - yb > -eps && ay - yb < eps) aPos = h + (ax - xl);
			else if (ax - xr > -eps && ax - xr < eps) aPos = h + w + (yb - ay);
			else if (ay - yt > -eps && ay - yt < eps) aPos = 2 * h + w + (xr - ax);

			let bPos = -1;
			if (bx - xl < eps && bx - xl > -eps) bPos = by - yt;
			else if (by - yb > -eps && by - yb < eps) bPos = h + (bx - xl);
			else if (bx - xr > -eps && bx - xr < eps) bPos = h + w + (yb - by);
			else if (by - yt > -eps && by - yt < eps) bPos = 2 * h + w + (xr - bx);

			// For lSite cell: walk va->vb, so va is entry-from-bbox, vb is exit-to-bbox.
			// For rSite cell: walk vb->va, so vb is entry, va is exit.
			if (aPos >= 0) {
				let evL = cellEvents[lId];
				if (evL === undefined) cellEvents[lId] = evL = [];
				evL.push(aPos, ax, ay, 0); // entry for lSite
				let evR = cellEvents[rId];
				if (evR === undefined) cellEvents[rId] = evR = [];
				evR.push(aPos, ax, ay, 1); // exit for rSite
			}
			if (bPos >= 0) {
				let evL = cellEvents[lId];
				if (evL === undefined) cellEvents[lId] = evL = [];
				evL.push(bPos, bx, by, 1); // exit for lSite
				let evR = cellEvents[rId];
				if (evR === undefined) cellEvents[rId] = evR = [];
				evR.push(bPos, bx, by, 0); // entry for rSite
			}
		}

		// Per-cell bbox closure. For each border cell, sort events by CCW
		// position (with isExit as a tiebreak so exits precede entries at the
		// same position), then pair each exit with the immediately following
		// entry (with wrap). Add shoelace for the bbox walk between them,
		// crossing 0-3 corners.
		const cornerXs = [xl, xr, xr, xl];
		const cornerYs = [yb, yb, yt, yt];
		const cornerPoses = [h, h + w, 2 * h + w, perim];
		for (let cellIdx = 0; cellIdx < n; cellIdx++) {
			const ev = cellEvents[cellIdx];
			if (ev === undefined) continue;
			const m = ev.length >>> 2;
			if (m === 0) continue;

			// Repack into tuples to sort. m is small (typically 2-8).
			const tuples: { pos: number; x: number; y: number; isExit: number }[] = new Array(m);
			for (let k = 0; k < m; k++) {
				const o = k << 2;
				tuples[k] = { pos: ev[o], x: ev[o + 1], y: ev[o + 2], isExit: ev[o + 3] };
			}
			tuples.sort((a, b) => a.pos - b.pos || b.isExit - a.isExit);

			for (let k = 0; k < m; k++) {
				if (tuples[k].isExit !== 1) continue;
				const exitT = tuples[k];
				const entryT = tuples[(k + 1) % m];
				// Walk CCW from exitT to entryT, crossing 0-3 corners.
				const exitPos = exitT.pos;
				let walkLen = entryT.pos - exitPos;
				if (walkLen <= 0) walkLen += perim;
				const walkEnd = exitPos + walkLen;

				let curX = exitT.x;
				let curY = exitT.y;
				for (let pass = 0; pass < 2; pass++) {
					const off = pass === 0 ? 0 : perim;
					let broke = false;
					for (let c = 0; c < 4; c++) {
						const cp = cornerPoses[c] + off;
						if (cp <= exitPos) continue;
						if (cp >= walkEnd) {
							broke = true;
							break;
						}
						const nx = cornerXs[c];
						const ny = cornerYs[c];
						const cross = curX * ny - curY * nx;
						cellArea[cellIdx] += cross;
						cellSumX[cellIdx] += (curX + nx) * cross;
						cellSumY[cellIdx] += (curY + ny) * cross;
						curX = nx;
						curY = ny;
					}
					if (broke) break;
				}
				// Final segment from current position to entry point.
				const nx = entryT.x;
				const ny = entryT.y;
				const cross = curX * ny - curY * nx;
				cellArea[cellIdx] += cross;
				cellSumX[cellIdx] += (curX + nx) * cross;
				cellSumY[cellIdx] += (curY + ny) * cross;
			}
		}

		// Centroid = sum / (3 * area). For degenerate cells (no edges or area
		// near zero) keep the site's existing position so Lloyd is a no-op.
		for (let i = 0; i < n; i++) {
			const a = cellArea[i];
			const absA = a < 0 ? -a : a;
			if (absA > eps) {
				const inv3a = 1 / (3 * a);
				outX[i] = cellSumX[i] * inv3a;
				outY[i] = cellSumY[i] * inv3a;
			} else {
				// cells[i].site has id === i by sweep construction; sites[] param is
				// in input order so cannot be indexed by cell id.
				const s = this.cells[i].site;
				outX[i] = s.x;
				outY[i] = s.y;
			}
		}
	}

	//
	// private methods
	//

	private equalWithEpsilon(a, b: number): boolean {
		return Math.abs(a - b) < EPSILON;
	}

	private greaterThanWithEpsilon(a, b: number): boolean {
		return a - b > EPSILON;
	}

	private greaterThanOrEqualWithEpsilon(a, b: number): boolean {
		return b - a < EPSILON;
	}

	private lessThanWithEpsilon(a, b: number): boolean {
		return b - a > EPSILON;
	}

	private lessThanOrEqualWithEpsilon(a, b: number): boolean {
		return a - b < EPSILON;
	}

	// ---------------------------------------------------------------------------
	// Helper: Quantize sites
	// rhill 2013-10-12:
	// This is to solve https://github.com/gorhill/Javascript-Voronoi/issues/15
	// Since not all users will end up using the kind of coord values which would
	// cause the issue to arise, I chose to let the user decide whether or not
	// he should sanitize his coord values through this helper. This way, for
	// those users who uses coord values which are known to be fine, no overhead is
	// added.
	private quantizeSites(sites: Site[]) {
		let eps = EPSILON,
			n = sites.length,
			site;
		while (n--) {
			site = sites[n];
			site.x = Math.floor(site.x / eps) * eps;
			site.y = Math.floor(site.y / eps) * eps;
		}
	}

	// ---------------------------------------------------------------------------
	// Helper: Recycle diagram: all vertex, edge and cell objects are
	// "surrendered" to the Voronoi object for reuse.
	// TODO: rhill-voronoi-core v2: more performance to be gained
	// when I change the semantic of what is returned.
	private recycle(diagram: Diagram) {
		if (diagram) {
			if (diagram instanceof Diagram) {
				this.toRecycle = diagram;
			} else {
				throw "Voronoi.recycleDiagram() > Need a Diagram object.";
			}
		}
	}

	private reset(): void {
		if (!this.beachTree) {
			this.beachTree = new RBTreeIdx();
			this.beachPool = new BeachPool(1024);
			this.circleHeap = new CircleEventHeap(1024);
			this.eventArcIdx = new Int32Array(1024);
			this.eventX = new Float64Array(1024);
			this.eventYcenter = new Float64Array(1024);
			this.eventCapacity = 1024;
		}

		// Pools and event arrays retain their capacity across compute() calls;
		// resetting just rolls size + free-list back to zero.
		this.beachPool.reset();
		this.beachTree.root = NIL;
		this.circleHeap.clear();
		this.eventCount = 0;
		this.vertices = [];
		this.edges = [];
		this.cells = [];
	}

	private ensureEventCapacity(min: number): void {
		if (this.eventCapacity >= min) return;
		let newCap = this.eventCapacity || 1024;
		while (newCap < min) newCap *= 2;
		const newArc = new Int32Array(newCap);
		const newX = new Float64Array(newCap);
		const newYc = new Float64Array(newCap);
		newArc.set(this.eventArcIdx);
		newX.set(this.eventX);
		newYc.set(this.eventYcenter);
		this.eventArcIdx = newArc;
		this.eventX = newX;
		this.eventYcenter = newYc;
		this.eventCapacity = newCap;
	}

	private createCell(site: Site): Cell {
		let cell = this.cellJunkyard.pop();
		if (cell) {
			return cell.init(site);
		}
		return new Cell(site);
	}

	private createHalfedge(edge: Edge, lSite: Site, rSite: Site): Halfedge {
		return new Halfedge(edge, lSite, rSite);
	}

	private createVertex(x: number, y: number) {
		let v = this.vertexJunkyard.pop();
		if (!v) {
			v = new Vertex(x, y);
		} else {
			v.x = x;
			v.y = y;
		}

		this.vertices.push(v);
		return v;
	}

	// this create and add an edge to internal collection, and also create
	// two halfedges which are added to each site's counterclockwise array
	// of halfedges.
	private createEdge(lSite: Site, rSite: Site, va: Vertex = null, vb: Vertex = null): Edge {
		let edge = this.edgeJunkyard.pop();
		if (!edge) {
			edge = new Edge(lSite, rSite);
		} else {
			edge.lSite = lSite;
			edge.rSite = rSite;
			edge.va = edge.vb = null;
		}

		this.edges.push(edge);
		if (va) {
			this.setEdgeStartpoint(edge, lSite, rSite, va);
		}
		if (vb) {
			this.setEdgeEndpoint(edge, lSite, rSite, vb);
		}
		if (!this.skipHalfedges) {
			this.cells[lSite.id].halfedges.push(this.createHalfedge(edge, lSite, rSite));
			this.cells[rSite.id].halfedges.push(this.createHalfedge(edge, rSite, lSite));
		}
		return edge;
	}

	private createBorderEdge(lSite: Site, va: Vertex, vb: Vertex): Edge {
		let edge = this.edgeJunkyard.pop();
		if (!edge) {
			edge = new Edge(lSite, null);
		} else {
			edge.lSite = lSite;
			edge.rSite = null;
		}
		edge.va = va;
		edge.vb = vb;

		this.edges.push(edge);
		return edge;
	}

	private setEdgeStartpoint(edge: Edge, lSite: Site, rSite: Site, vertex: Vertex): void {
		if (!edge.va && !edge.vb) {
			edge.va = vertex;
			edge.lSite = lSite;
			edge.rSite = rSite;
		} else if (edge.lSite === rSite) {
			edge.vb = vertex;
		} else {
			edge.va = vertex;
		}
	}

	private setEdgeEndpoint(edge: Edge, lSite: Site, rSite: Site, vertex: Vertex): void {
		this.setEdgeStartpoint(edge, rSite, lSite, vertex);
	}

	// rhill 2011-06-02: A lot of Beachsection instanciations
	// occur during the computation of the Voronoi diagram,
	// somewhere between the number of sites and twice the
	// number of sites, while the number of Beachsections on the
	// beachline at any given time is comparatively low. For this
	// reason, we reuse already created Beachsections, in order
	// to avoid new memory allocation. This resulted in a measurable
	// performance gain.
	private createBeachsection(site: Site): number {
		return this.beachPool.alloc(site);
	}

	// calculate the left break point of a particular beach section,
	// given a particular sweep line
	private leftBreakPoint(arc: number, directrix: number): number {
		// http://en.wikipedia.org/wiki/Parabola
		// http://en.wikipedia.org/wiki/Quadratic_equation
		// h1 = x1,
		// k1 = (y1+directrix)/2,
		// h2 = x2,
		// k2 = (y2+directrix)/2,
		// p1 = k1-directrix,
		// a1 = 1/(4*p1),
		// b1 = -h1/(2*p1),
		// c1 = h1*h1/(4*p1)+k1,
		// p2 = k2-directrix,
		// a2 = 1/(4*p2),
		// b2 = -h2/(2*p2),
		// c2 = h2*h2/(4*p2)+k2,
		// x = (-(b2-b1) + Math.sqrt((b2-b1)*(b2-b1) - 4*(a2-a1)*(c2-c1))) / (2*(a2-a1))
		// When x1 become the x-origin:
		// h1 = 0,
		// k1 = (y1+directrix)/2,
		// h2 = x2-x1,
		// k2 = (y2+directrix)/2,
		// p1 = k1-directrix,
		// a1 = 1/(4*p1),
		// b1 = 0,
		// c1 = k1,
		// p2 = k2-directrix,
		// a2 = 1/(4*p2),
		// b2 = -h2/(2*p2),
		// c2 = h2*h2/(4*p2)+k2,
		// x = (-b2 + Math.sqrt(b2*b2 - 4*(a2-a1)*(c2-k1))) / (2*(a2-a1)) + x1

		// change code below at your own risk: care has been taken to
		// reduce errors due to computers' finite arithmetic precision.
		// Maybe can still be improved, will see if any more of this
		// kind of errors pop up again.
		const bp = this.beachPool;
		const siteX = bp.siteX;
		const siteY = bp.siteY;
		let rfocx = siteX[arc],
			rfocy = siteY[arc],
			pby2 = rfocy - directrix;

		// parabola in degenerate case where focus is on directrix
		if (!pby2) {
			return rfocx;
		}

		const lArc = bp.links.prev[arc];
		if (lArc === NIL) {
			return -Infinity;
		}

		let lfocx = siteX[lArc],
			lfocy = siteY[lArc],
			plby2 = lfocy - directrix;

		// parabola in degenerate case where focus is on directrix
		if (!plby2) {
			return lfocx;
		}

		let hl = lfocx - rfocx,
			aby2 = 1 / pby2 - 1 / plby2,
			b = hl / plby2;

		if (aby2) {
			return (
				(-b + Math.sqrt(b * b - 2 * aby2 * ((hl * hl) / (-2 * plby2) - lfocy + plby2 / 2 + rfocy - pby2 / 2))) /
					aby2 +
				rfocx
			);
		}

		// both parabolas have same distance to directrix, thus break point is midway
		return (rfocx + lfocx) / 2;
	}

	// calculate the right break point of a particular beach section,
	// given a particular directrix
	private rightBreakPoint(arc: number, directrix: number): number {
		const bp = this.beachPool;
		const rArc = bp.links.next[arc];
		if (rArc !== NIL) {
			return this.leftBreakPoint(rArc, directrix);
		}
		const sy = bp.siteY[arc];
		return sy === directrix ? bp.siteX[arc] : Infinity;
	}

	private detachBeachsection(beachsection: number): void {
		this.detachCircleEvent(beachsection); // detach potentially attached circle event
		this.beachTree.removeNode(this.beachPool.links, beachsection); // remove from RB-tree
		this.beachPool.free(beachsection); // mark for reuse
	}

	private removeBeachsection(beachsection: number): void {
		const bp = this.beachPool;
		const bPrev = bp.links.prev;
		const bNext = bp.links.next;
		const bCircle = bp.circleEventIdx;
		const bSite = bp.siteRef;
		const bEdge = bp.edgeRef;
		const eventX = this.eventX;
		const eventYc = this.eventYcenter;

		const circle = bCircle[beachsection];
		const x = eventX[circle];
		const y = eventYc[circle];
		const vertex = this.createVertex(x, y);
		let previous = bPrev[beachsection];
		let next = bNext[beachsection];
		const disappearingTransitions: number[] = [beachsection];
		const abs_fn = Math.abs;

		// remove collapsed beachsection from beachline
		this.detachBeachsection(beachsection);

		// there could be more than one empty arc at the deletion point, this
		// happens when more than two edges are linked by the same vertex,
		// so we will collect all those edges by looking up both sides of
		// the deletion point.
		// by the way, there is *always* a predecessor/successor to any collapsed
		// beach section, it's just impossible to have a collapsing first/last
		// beach sections on the beachline, since they obviously are unconstrained
		// on their left/right side.

		// look left
		let lArc = previous;
		let lCircle = bCircle[lArc];
		while (lCircle !== NIL && abs_fn(x - eventX[lCircle]) < EPSILON && abs_fn(y - eventYc[lCircle]) < EPSILON) {
			previous = bPrev[lArc];
			disappearingTransitions.unshift(lArc);
			this.detachBeachsection(lArc); // mark for reuse
			lArc = previous;
			lCircle = bCircle[lArc];
		}

		// even though it is not disappearing, I will also add the beach section
		// immediately to the left of the left-most collapsed beach section, for
		// convenience, since we need to refer to it later as this beach section
		// is the 'left' site of an edge for which a start point is set.
		disappearingTransitions.unshift(lArc);
		this.detachCircleEvent(lArc);

		// look right
		let rArc = next;
		let rCircle = bCircle[rArc];
		while (rCircle !== NIL && abs_fn(x - eventX[rCircle]) < EPSILON && abs_fn(y - eventYc[rCircle]) < EPSILON) {
			next = bNext[rArc];
			disappearingTransitions.push(rArc);
			this.detachBeachsection(rArc); // mark for reuse
			rArc = next;
			rCircle = bCircle[rArc];
		}

		// we also have to add the beach section immediately to the right of the
		// right-most collapsed beach section, since there is also a disappearing
		// transition representing an edge's start point on its left.
		disappearingTransitions.push(rArc);
		this.detachCircleEvent(rArc);

		// walk through all the disappearing transitions between beach sections and
		// set the start point of their (implied) edge.
		const nArcs = disappearingTransitions.length;
		let iArc: number;
		for (iArc = 1; iArc < nArcs; iArc++) {
			rArc = disappearingTransitions[iArc];
			lArc = disappearingTransitions[iArc - 1];
			this.setEdgeStartpoint(bEdge[rArc], bSite[lArc], bSite[rArc], vertex);
		}

		// create a new edge as we have now a new transition between
		// two beach sections which were previously not adjacent.
		// since this edge appears as a new vertex is defined, the vertex
		// actually define an end point of the edge (relative to the site
		// on the left)
		lArc = disappearingTransitions[0];
		rArc = disappearingTransitions[nArcs - 1];
		bEdge[rArc] = this.createEdge(bSite[lArc], bSite[rArc], undefined, vertex);

		// create circle events if any for beach sections left in the beachline
		// adjacent to collapsed sections
		this.attachCircleEvent(lArc);
		this.attachCircleEvent(rArc);
	}

	private addBeachsection(site: Site): void {
		const x = site.x;
		const directrix = site.y;
		const bp = this.beachPool;
		const bLinks = bp.links;
		const bLeft = bLinks.left;
		const bRight = bLinks.right;
		const bPrev = bLinks.prev;
		const bNext = bLinks.next;
		const bSite = bp.siteRef;
		const bEdge = bp.edgeRef;

		// find the left and right beach sections which will surround the newly
		// created beach section.
		// rhill 2011-06-01: This loop is one of the most often executed,
		// hence we expand in-place the comparison-against-epsilon calls.
		let lArc = NIL;
		let rArc = NIL;
		let dxl: number;
		let dxr: number;
		let node = this.beachTree.root;

		while (node !== NIL) {
			dxl = this.leftBreakPoint(node, directrix) - x;

			// x lessThanWithEpsilon xl => falls somewhere before the left edge of the beachsection
			if (dxl > EPSILON) {
				node = bLeft[node];
			} else {
				dxr = x - this.rightBreakPoint(node, directrix);

				// x greaterThanWithEpsilon xr => falls somewhere after the right edge of the beachsection
				if (dxr > EPSILON) {
					if (bRight[node] === NIL) {
						lArc = node;
						break;
					}
					node = bRight[node];
				} else {
					// x equalWithEpsilon xl => falls exactly on the left edge of the beachsection
					if (dxl > -EPSILON) {
						lArc = bPrev[node];
						rArc = node;
					}

					// x equalWithEpsilon xr => falls exactly on the right edge of the beachsection
					else if (dxr > -EPSILON) {
						lArc = node;
						rArc = bNext[node];
					}

					// falls exactly somewhere in the middle of the beachsection
					else {
						lArc = rArc = node;
					}

					break;
				}
			}
		}

		// at this point, keep in mind that lArc and/or rArc could be NIL.

		// create a new beach section for the site and add it to the RB-tree
		const newArc = this.createBeachsection(site);
		this.beachTree.insertSuccessor(bLinks, lArc, newArc);

		// [NIL,NIL]
		// least likely case: new beach section is the first beach section on the
		// beachline.
		if (lArc === NIL && rArc === NIL) {
			return;
		}

		// [lArc,rArc] where lArc == rArc
		// most likely case: new beach section splits an existing beach section.
		if (lArc === rArc) {
			// invalidate circle event of split beach section
			this.detachCircleEvent(lArc);

			// split the beach section into two separate beach sections
			rArc = this.createBeachsection(bSite[lArc]);
			this.beachTree.insertSuccessor(bLinks, newArc, rArc);

			// since we have a new transition between two beach sections,
			// a new edge is born
			const newEdge = this.createEdge(bSite[lArc], site);
			bEdge[newArc] = newEdge;
			bEdge[rArc] = newEdge;

			// check whether the left and right beach sections are collapsing
			// and if so create circle events.
			this.attachCircleEvent(lArc);
			this.attachCircleEvent(rArc);
			return;
		}

		// [lArc,NIL]
		// even less likely case: new beach section is the *last* beach section
		// on the beachline.
		if (lArc !== NIL && rArc === NIL) {
			bEdge[newArc] = this.createEdge(bSite[lArc], site);
			return;
		}

		// [NIL,rArc] is impossible per the original algorithm and intentionally
		// not tested here.

		// [lArc,rArc] where lArc != rArc
		// new beach section falls *exactly* in between two existing beach sections.
		if (lArc !== rArc) {
			// invalidate circle events of left and right sites
			this.detachCircleEvent(lArc);
			this.detachCircleEvent(rArc);

			const lSite = bSite[lArc];
			const ax = lSite.x;
			const ay = lSite.y;
			const bx = site.x - ax;
			const by = site.y - ay;
			const rSite = bSite[rArc];
			const cx = rSite.x - ax;
			const cy = rSite.y - ay;
			const d = 2 * (bx * cy - by * cx);
			const hb = bx * bx + by * by;
			const hc = cx * cx + cy * cy;
			const vertex = this.createVertex((cy * hb - by * hc) / d + ax, (bx * hc - cx * hb) / d + ay);

			// one transition disappears
			this.setEdgeStartpoint(bEdge[rArc], lSite, rSite, vertex);

			// two new transitions appear at the new vertex location
			bEdge[newArc] = this.createEdge(lSite, site, undefined, vertex);
			bEdge[rArc] = this.createEdge(site, rSite, undefined, vertex);

			// check whether the left and right beach sections are collapsing
			// and if so create circle events.
			this.attachCircleEvent(lArc);
			this.attachCircleEvent(rArc);
			return;
		}
	}

	private attachCircleEvent(arc: number): void {
		const bp = this.beachPool;
		const bLinks = bp.links;

		const lArc = bLinks.prev[arc];
		const rArc = bLinks.next[arc];
		if (lArc === NIL || rArc === NIL) {
			return;
		} // does that ever happen?

		const bSiteRef = bp.siteRef;
		const lSite = bSiteRef[lArc];
		const rSite = bSiteRef[rArc];

		// If site of left beachsection is same as site of
		// right beachsection, there can't be convergence
		if (lSite === rSite) {
			return;
		}

		// Find the circumscribed circle for the three sites associated
		// with the beachsection triplet.
		// rhill 2011-05-26: It is more efficient to calculate in-place
		// rather than getting the resulting circumscribed circle from an
		// object returned by calling Voronoi.circumcircle()
		// http://mathforum.org/library/drmath/view/55002.html
		// Except that I bring the origin at cSite to simplify calculations.
		// The bottom-most part of the circumcircle is our Fortune 'circle
		// event', and its center is a vertex potentially part of the final
		// Voronoi diagram.
		const siteX = bp.siteX;
		const siteY = bp.siteY;
		const bx = siteX[arc];
		const by = siteY[arc];
		const ax = siteX[lArc] - bx;
		const ay = siteY[lArc] - by;
		const cx = siteX[rArc] - bx;
		const cy = siteY[rArc] - by;

		// If points l->c->r are clockwise, then center beach section does not
		// collapse, hence it can't end up as a vertex.
		// rhill 2011-05-21: 1e-12 finite-precision guard.
		const d = 2 * (ax * cy - ay * cx);
		if (d >= -2e-12) {
			return;
		}

		const ha = ax * ax + ay * ay;
		const hc = cx * cx + cy * cy;
		const px = (cy * ha - ay * hc) / d;
		const py = (ax * hc - cx * ha) / d;
		const ycenter = py + by;
		const eventX = px + bx;
		const eventY = ycenter + Math.sqrt(px * px + py * py); // y bottom

		// Allocate a new event id (monotonic counter; reset per compute()).
		const ev = this.eventCount++;
		if (ev >= this.eventCapacity) {
			this.ensureEventCapacity(ev + 1);
		}
		this.eventArcIdx[ev] = arc;
		this.eventX[ev] = eventX;
		this.eventYcenter[ev] = ycenter;
		bp.circleEventIdx[arc] = ev;

		// Tie-break on x: site coords are seeded from a 16-bit randomizer, so
		// ties on yBottom are common and must be ordered deterministically.
		this.circleHeap.push(eventY, eventX, ev);
	}

	private detachCircleEvent(arc: number): void {
		// Lazy invalidation: just clear the back-pointer. The corresponding
		// heap entry (if any) is filtered when it surfaces at the top.
		this.beachPool.circleEventIdx[arc] = NIL;
	}

	// connect dangling edges (not if a cursory test tells us
	// it is not going to be visible.
	// return value:
	//   false: the dangling endpoint couldn't be connected
	//   true: the dangling endpoint could be connected
	private connectEdge(edge: Edge, bbox: BoundingBox) {
		// skip if end point already connected
		let vb = edge.vb;
		if (vb) {
			return true;
		}

		// make local copy for performance purpose
		let va = edge.va,
			xl = bbox.xl,
			xr = bbox.xr,
			yt = bbox.yt,
			yb = bbox.yb,
			lSite = edge.lSite,
			rSite = edge.rSite,
			lx = lSite.x,
			ly = lSite.y,
			rx = rSite.x,
			ry = rSite.y,
			fx = (lx + rx) / 2,
			fy = (ly + ry) / 2,
			fm,
			fb;

		// if we reach here, this means cells which use this edge will need
		// to be closed, whether because the edge was removed, or because it
		// was connected to the bounding box.
		this.cells[lSite.id].closeMe = true;
		this.cells[rSite.id].closeMe = true;

		// get the line equation of the bisector if line is not vertical
		if (ry !== ly) {
			fm = (lx - rx) / (ry - ly);
			fb = fy - fm * fx;
		}

		// remember, direction of line (relative to left site):
		// upward: left.x < right.x
		// downward: left.x > right.x
		// horizontal: left.x == right.x
		// upward: left.x < right.x
		// rightward: left.y < right.y
		// leftward: left.y > right.y
		// vertical: left.y == right.y

		// depending on the direction, find the best side of the
		// bounding box to use to determine a reasonable start point

		// rhill 2013-12-02:
		// While at it, since we have the values which define the line,
		// clip the end of va if it is outside the bbox.
		// https://github.com/gorhill/Javascript-Voronoi/issues/15
		// TODO: Do all the clipping here rather than rely on Liang-Barsky
		// which does not do well sometimes due to loss of arithmetic
		// precision. The code here doesn't degrade if one of the vertex is
		// at a huge distance.

		// special case: vertical line
		if (fm === undefined) {
			// doesn't intersect with viewport
			if (fx < xl || fx >= xr) {
				return false;
			}

			// downward
			if (lx > rx) {
				if (!va || va.y < yt) {
					va = this.createVertex(fx, yt);
				} else if (va.y >= yb) {
					return false;
				}
				vb = this.createVertex(fx, yb);
			}
			// upward
			else {
				if (!va || va.y > yb) {
					va = this.createVertex(fx, yb);
				} else if (va.y < yt) {
					return false;
				}
				vb = this.createVertex(fx, yt);
			}
		}

		// closer to vertical than horizontal, connect start point to the
		// top or bottom side of the bounding box
		else if (fm < -1 || fm > 1) {
			// downward
			if (lx > rx) {
				if (!va || va.y < yt) {
					va = this.createVertex((yt - fb) / fm, yt);
				} else if (va.y >= yb) {
					return false;
				}
				vb = this.createVertex((yb - fb) / fm, yb);
			}
			// upward
			else {
				if (!va || va.y > yb) {
					va = this.createVertex((yb - fb) / fm, yb);
				} else if (va.y < yt) {
					return false;
				}
				vb = this.createVertex((yt - fb) / fm, yt);
			}
		}

		// closer to horizontal than vertical, connect start point to the
		// left or right side of the bounding box
		else {
			// rightward
			if (ly < ry) {
				if (!va || va.x < xl) {
					va = this.createVertex(xl, fm * xl + fb);
				} else if (va.x >= xr) {
					return false;
				}
				vb = this.createVertex(xr, fm * xr + fb);
			}

			// leftward
			else {
				if (!va || va.x > xr) {
					va = this.createVertex(xr, fm * xr + fb);
				} else if (va.x < xl) {
					return false;
				}
				vb = this.createVertex(xl, fm * xl + fb);
			}
		}

		edge.va = va;
		edge.vb = vb;

		return true;
	}

	// line-clipping code taken from:
	//   Liang-Barsky function by Daniel White
	//   http://www.skytopia.com/project/articles/compsci/clipping.html
	// Thanks!
	// A bit modified to minimize code paths
	private clipEdge(edge: Edge, bbox: BoundingBox): boolean {
		let ax = edge.va.x,
			ay = edge.va.y,
			bx = edge.vb.x,
			by = edge.vb.y,
			t0 = 0,
			t1 = 1,
			dx = bx - ax,
			dy = by - ay;

		// left
		let q = ax - bbox.xl;
		if (dx === 0 && q < 0) {
			return false;
		}

		let r = -q / dx;
		if (dx < 0) {
			if (r < t0) {
				return false;
			}
			if (r < t1) {
				t1 = r;
			}
		} else if (dx > 0) {
			if (r > t1) {
				return false;
			}
			if (r > t0) {
				t0 = r;
			}
		}

		// right
		q = bbox.xr - ax;
		if (dx === 0 && q < 0) {
			return false;
		}
		r = q / dx;
		if (dx < 0) {
			if (r > t1) {
				return false;
			}
			if (r > t0) {
				t0 = r;
			}
		} else if (dx > 0) {
			if (r < t0) {
				return false;
			}
			if (r < t1) {
				t1 = r;
			}
		}

		// top
		q = ay - bbox.yt;
		if (dy === 0 && q < 0) {
			return false;
		}
		r = -q / dy;
		if (dy < 0) {
			if (r < t0) {
				return false;
			}
			if (r < t1) {
				t1 = r;
			}
		} else if (dy > 0) {
			if (r > t1) {
				return false;
			}
			if (r > t0) {
				t0 = r;
			}
		}

		// bottom
		q = bbox.yb - ay;
		if (dy === 0 && q < 0) {
			return false;
		}
		r = q / dy;
		if (dy < 0) {
			if (r > t1) {
				return false;
			}
			if (r > t0) {
				t0 = r;
			}
		} else if (dy > 0) {
			if (r < t0) {
				return false;
			}
			if (r < t1) {
				t1 = r;
			}
		}

		// if we reach this point, Voronoi edge is within bbox

		// if t0 > 0, va needs to change
		// rhill 2011-06-03: we need to create a new vertex rather
		// than modifying the existing one, since the existing
		// one is likely shared with at least another edge
		if (t0 > 0) {
			edge.va = this.createVertex(ax + t0 * dx, ay + t0 * dy);
		}

		// if t1 < 1, vb needs to change
		// rhill 2011-06-03: we need to create a new vertex rather
		// than modifying the existing one, since the existing
		// one is likely shared with at least another edge
		if (t1 < 1) {
			edge.vb = this.createVertex(ax + t1 * dx, ay + t1 * dy);
		}

		// va and/or vb were clipped, thus we will need to close
		// cells which use this edge.
		if (t0 > 0 || t1 < 1) {
			this.cells[edge.lSite.id].closeMe = true;
			this.cells[edge.rSite.id].closeMe = true;
		}

		return true;
	}

	// Connect/cut edges at bounding box
	private clipEdges(bbox: BoundingBox) {
		// connect all dangling edges to bounding box
		// or get rid of them if it can't be done
		let edges = this.edges,
			iEdge = edges.length,
			edge,
			abs_fn = Math.abs;

		// iterate backward so we can splice safely
		while (iEdge--) {
			edge = edges[iEdge];
			// edge is removed if:
			//   it is wholly outside the bounding box
			//   it is looking more like a point than a line
			if (
				!this.connectEdge(edge, bbox) ||
				!this.clipEdge(edge, bbox) ||
				(abs_fn(edge.va.x - edge.vb.x) < EPSILON && abs_fn(edge.va.y - edge.vb.y) < EPSILON)
			) {
				edge.va = edge.vb = null;
				edges.splice(iEdge, 1);
			}
		}
	}

	// Close the cells.
	// The cells are bound by the supplied bounding box.
	// Each cell refers to its associated site, and a list
	// of halfedges ordered counterclockwise.
	private closeCells(bbox: BoundingBox) {
		let xl = bbox.xl,
			xr = bbox.xr,
			yt = bbox.yt,
			yb = bbox.yb,
			cells = this.cells,
			iCell = cells.length,
			cell,
			iLeft,
			halfedges,
			nHalfedges,
			edge,
			va,
			vb,
			vz,
			lastBorderSegment,
			abs_fn = Math.abs;

		while (iCell--) {
			cell = cells[iCell];
			// prune, order halfedges counterclockwise, then add missing ones
			// required to close cells
			if (!cell.prepareHalfedges()) {
				continue;
			}

			if (!cell.closeMe) {
				continue;
			}

			// find first 'unclosed' point.
			// an 'unclosed' point will be the end point of a halfedge which
			// does not match the start point of the following halfedge
			halfedges = cell.halfedges;
			nHalfedges = halfedges.length;
			// special case: only one site, in which case, the viewport is the cell
			// ...

			// all other cases
			iLeft = 0;
			while (iLeft < nHalfedges) {
				va = halfedges[iLeft].getEndpoint();
				vz = halfedges[(iLeft + 1) % nHalfedges].getStartpoint();
				// if end point is not equal to start point, we need to add the missing
				// halfedge(s) up to vz
				if (abs_fn(va.x - vz.x) >= EPSILON || abs_fn(va.y - vz.y) >= EPSILON) {
					// rhill 2013-12-02:
					// "Holes" in the halfedges are not necessarily always adjacent.
					// https://github.com/gorhill/Javascript-Voronoi/issues/16

					// find entry point:
					switch (true) {
						// walk downward along left side
						case this.equalWithEpsilon(va.x, xl) && this.lessThanWithEpsilon(va.y, yb):
							lastBorderSegment = this.equalWithEpsilon(vz.x, xl);
							vb = this.createVertex(xl, lastBorderSegment ? vz.y : yb);
							edge = this.createBorderEdge(cell.site, va, vb);
							iLeft++;
							halfedges.splice(iLeft, 0, this.createHalfedge(edge, cell.site, null));
							nHalfedges++;
							if (lastBorderSegment) {
								break;
							}
							va = vb;
						// fall through

						// walk rightward along bottom side
						case this.equalWithEpsilon(va.y, yb) && this.lessThanWithEpsilon(va.x, xr):
							lastBorderSegment = this.equalWithEpsilon(vz.y, yb);
							vb = this.createVertex(lastBorderSegment ? vz.x : xr, yb);
							edge = this.createBorderEdge(cell.site, va, vb);
							iLeft++;
							halfedges.splice(iLeft, 0, this.createHalfedge(edge, cell.site, null));
							nHalfedges++;
							if (lastBorderSegment) {
								break;
							}
							va = vb;
						// fall through

						// walk upward along right side
						case this.equalWithEpsilon(va.x, xr) && this.greaterThanWithEpsilon(va.y, yt):
							lastBorderSegment = this.equalWithEpsilon(vz.x, xr);
							vb = this.createVertex(xr, lastBorderSegment ? vz.y : yt);
							edge = this.createBorderEdge(cell.site, va, vb);
							iLeft++;
							halfedges.splice(iLeft, 0, this.createHalfedge(edge, cell.site, null));
							nHalfedges++;
							if (lastBorderSegment) {
								break;
							}
							va = vb;
						// fall through

						// walk leftward along top side
						case this.equalWithEpsilon(va.y, yt) && this.greaterThanWithEpsilon(va.x, xl):
							lastBorderSegment = this.equalWithEpsilon(vz.y, yt);
							vb = this.createVertex(lastBorderSegment ? vz.x : xl, yt);
							edge = this.createBorderEdge(cell.site, va, vb);
							iLeft++;
							halfedges.splice(iLeft, 0, this.createHalfedge(edge, cell.site, null));
							nHalfedges++;
							if (lastBorderSegment) {
								break;
							}
							va = vb;
							// fall through

							// walk downward along left side
							lastBorderSegment = this.equalWithEpsilon(vz.x, xl);
							vb = this.createVertex(xl, lastBorderSegment ? vz.y : yb);
							edge = this.createBorderEdge(cell.site, va, vb);
							iLeft++;
							halfedges.splice(iLeft, 0, this.createHalfedge(edge, cell.site, null));
							nHalfedges++;
							if (lastBorderSegment) {
								break;
							}
							va = vb;
							// fall through

							// walk rightward along bottom side
							lastBorderSegment = this.equalWithEpsilon(vz.y, yb);
							vb = this.createVertex(lastBorderSegment ? vz.x : xr, yb);
							edge = this.createBorderEdge(cell.site, va, vb);
							iLeft++;
							halfedges.splice(iLeft, 0, this.createHalfedge(edge, cell.site, null));
							nHalfedges++;
							if (lastBorderSegment) {
								break;
							}
							va = vb;
							// fall through

							// walk upward along right side
							lastBorderSegment = this.equalWithEpsilon(vz.x, xr);
							vb = this.createVertex(xr, lastBorderSegment ? vz.y : yt);
							edge = this.createBorderEdge(cell.site, va, vb);
							iLeft++;
							halfedges.splice(iLeft, 0, this.createHalfedge(edge, cell.site, null));
							nHalfedges++;
							if (lastBorderSegment) {
								break;
							}
						// fall through

						default:
							throw "Voronoi.closeCells() > this makes no sense!";
					}
				}

				iLeft++;
			}

			cell.closeMe = false;
		}
	}
}
